<script setup lang="ts">
import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; import { getApiErrorMessage } from '../api'
const form = reactive({ email:'admin@example.com', password:'password' }); const submitting = ref(false); const error = ref(''); const auth = useAuthStore(); const router = useRouter()
async function submit() { submitting.value=true; error.value=''; try { await auth.login(form.email, form.password); await router.push('/admin') } catch (cause) { error.value=getApiErrorMessage(cause) } finally { submitting.value=false } }
</script>
<template><main class="login-page"><section class="login-panel"><div class="brand brand--login"><span class="brand-mark">C</span><span>Cyberboard</span></div><p class="eyebrow">CONTROL PLANE</p><h1>登录管理后台</h1><p class="login-description">管理用户、订阅、节点和配置发布。</p><form @submit.prevent="submit"><label>邮箱<input v-model="form.email" type="email" autocomplete="username" required :disabled="submitting" /></label><label>密码<input v-model="form.password" type="password" autocomplete="current-password" required :disabled="submitting" /></label><p v-if="error" class="form-error" role="alert">{{ error }}</p><button class="primary-button" type="submit" :disabled="submitting">{{ submitting ? '正在验证…' : '登录' }}</button></form><p class="login-note">开发期提示：登录由控制面 API 验证，成功后会在本地保存会话令牌。</p></section></main></template>
